create table att_approval_history (created_at timestamp(6) not null, performed_on timestamp(6), updated_at timestamp(6) not null, id uuid not null, organization_id uuid not null, reference_id uuid, action varchar(50), module varchar(50), performed_by varchar(100), remarks varchar(500), primary key (id));
create table att_devices (created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, organization_id uuid not null, status varchar(20), device_type varchar(50), ip_address varchar(50), device_name varchar(100) not null, location varchar(100), primary key (id));
create table att_exceptions (resolved boolean, created_at timestamp(6) not null, resolved_at timestamp(6), updated_at timestamp(6) not null, employee_id uuid not null, id uuid not null, organization_id uuid not null, resolved_by uuid, severity varchar(20), exception_type varchar(50) not null, description varchar(500), primary key (id));
create table att_holiday_lists (year integer not null, created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, organization_id uuid not null, holiday_list_name varchar(100) not null, location_id varchar(100), primary key (id));
create table att_holidays (active boolean, holiday_date date not null, optional boolean, restricted_holiday boolean, created_at timestamp(6) not null, updated_at timestamp(6) not null, holiday_list_id uuid not null, id uuid not null, holiday_type varchar(50), country varchar(100), holiday_name varchar(100) not null, location varchar(100), state varchar(100), description varchar(500), primary key (id));
create table att_ip_mappings (created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, organization_id uuid not null, ip_address varchar(50) not null, location_id varchar(100), description varchar(255), primary key (id));
create table att_leave_applications (applied_on date, duration numeric(5,2), from_date date not null, to_date date not null, approved_at timestamp(6), created_at timestamp(6) not null, updated_at timestamp(6) not null, approver_id uuid, employee_id uuid not null, id uuid not null, leave_type_id uuid not null, organization_id uuid not null, from_session varchar(20), status varchar(20), to_session varchar(20), leave_number varchar(30), approval_remarks varchar(500), attachment varchar(500), cancel_reason varchar(500), reason varchar(1000), primary key (id));
create table att_leave_balances (available numeric(5,2), availed numeric(5,2), encashed numeric(5,2), granted numeric(5,2), lapsed numeric(5,2), opening_balance numeric(5,2), year integer not null, created_at timestamp(6) not null, updated_at timestamp(6) not null, employee_id uuid not null, id uuid not null, leave_type_id uuid not null, primary key (id));
create table att_leave_scheme_rules (annual_quota numeric(5,2), carry_forward numeric(5,2), encashable boolean, maximum_consecutive_days integer, medical_certificate_required boolean, minimum_notice integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, leave_type_id uuid not null, scheme_id uuid not null, accrual_frequency varchar(20), primary key (id));
create table att_leave_schemes (default_scheme boolean, created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, organization_id uuid not null, scheme_name varchar(100) not null, description varchar(500), primary key (id));
create table att_leave_types (active boolean, allow_half_day boolean, allow_hourly_leave boolean, maximum_days numeric(4,2), minimum_days numeric(4,2), notice_period_required integer, probation_allowed boolean, requires_approval boolean, requires_attachment boolean, created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, organization_id uuid not null, category varchar(20), code varchar(20), color varchar(20), gender_restriction varchar(20), icon varchar(50), name varchar(100) not null, description varchar(500), primary key (id));
create table att_lock_configurations (active boolean, lock_days integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, organization_id uuid not null, feature varchar(100) not null, primary key (id));
create table att_logs (created_at timestamp(6) not null, timestamp timestamp(6) not null, direction varchar(10), employee_id uuid not null, id uuid not null, organization_id uuid not null, source varchar(30), device varchar(100), primary key (id));
create table att_periods (attendance_count integer, employee_count integer, end_date date not null, month integer not null, start_date date not null, year integer not null, created_at timestamp(6) not null, locked_at timestamp(6), processed_on timestamp(6), updated_at timestamp(6) not null, id uuid not null, locked_by uuid, organization_id uuid not null, processed_by uuid, processing_status varchar(30), status varchar(30), period_name varchar(100) not null, remarks varchar(500), primary key (id));
create table att_permission_requests (end_time time(6), permission_date date not null, start_time time(6), total_hours numeric(4,2), approved_at timestamp(6), created_at timestamp(6) not null, updated_at timestamp(6) not null, approver_id uuid, employee_id uuid not null, id uuid not null, organization_id uuid not null, status varchar(20), permission_number varchar(30), permission_type varchar(50), approval_remarks varchar(500), attachment varchar(500), reason varchar(1000), primary key (id));
create table att_processed (absent_days numeric(5,2), final_payable_days numeric(5,2), gross_working_days numeric(5,2), half_days integer, holidays integer, late_days integer, leave_days numeric(5,2), lop_days numeric(5,2), overtime_hours numeric(5,2), payable_days numeric(5,2), present_days numeric(5,2), weekly_offs integer, created_at timestamp(6) not null, processed_on timestamp(6), updated_at timestamp(6) not null, employee_id uuid not null, id uuid not null, period_id uuid not null, processed_by uuid, status varchar(20), primary key (id));
create table att_records (attendance_date date not null, break_hours numeric(4,2), early_exit integer, late_by integer, overtime_hours numeric(4,2), regularized boolean, working_hours numeric(4,2), approved_at timestamp(6), check_in timestamp(6), check_out timestamp(6), created_at timestamp(6) not null, updated_at timestamp(6) not null, approved_by uuid, employee_id uuid not null, id uuid not null, organization_id uuid not null, shift_id uuid, approval_status varchar(20), regularization_status varchar(20), attendance_source varchar(30), status varchar(30), exception_type varchar(50), remarks varchar(500), primary key (id));
create table att_regularization_requests (actual_check_in time(6), actual_check_out time(6), date date not null, requested_check_in time(6), requested_check_out time(6), approved_at timestamp(6), created_at timestamp(6) not null, updated_at timestamp(6) not null, approver_id uuid, employee_id uuid not null, id uuid not null, organization_id uuid not null, status varchar(20), request_number varchar(30), approval_remarks varchar(500), attachment varchar(500), reason varchar(1000), primary key (id));
create table att_schemes (allow_mobile_attendance boolean, auto_regularization boolean, grace_minutes integer, half_day_hours numeric(4,2), minimum_hours numeric(4,2), require_live_validation boolean, created_at timestamp(6) not null, updated_at timestamp(6) not null, default_shift_id uuid, holiday_list_id uuid, id uuid not null, organization_id uuid not null, late_policy varchar(50), overtime_policy varchar(50), scheme_name varchar(100) not null, scheme_description varchar(500), weekend_configuration TEXT, primary key (id));
create table att_shift_rosters (month integer, overridden boolean, published boolean, roster_date date not null, week_number integer, year integer, created_at timestamp(6) not null, published_on timestamp(6), updated_at timestamp(6) not null, assigned_shift_id uuid not null, employee_id uuid not null, id uuid not null, organization_id uuid not null, published_by uuid, updated_by uuid, primary key (id));
create table att_shift_rotation_patterns (rotation_days integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, organization_id uuid not null, pattern_name varchar(100) not null, pattern_sequence TEXT, primary key (id));
create table att_shifts (active boolean, break_end time(6), break_start time(6), early_exit_grace_minutes integer, end_time time(6), flexible_shift boolean, full_day_hours numeric(4,2), grace_time integer, half_day_hours numeric(4,2), late_grace_minutes integer, night_shift boolean, overtime_allowed boolean, start_time time(6), weekly_hours numeric(4,2), created_at timestamp(6) not null, updated_at timestamp(6) not null, company_id uuid, id uuid not null, organization_id uuid not null, shift_code varchar(30), shift_name varchar(100) not null, description varchar(500), primary key (id));
